import sys

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    s = data[1]

    # Initialize counters
    open_count = 0
    close_count = 0
    question_count = 0

    # First pass: count the number of open, close, and question marks
    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            close_count += 1
        else:
            question_count += 1

    # Check if it's possible to form a valid sequence
    if open_count + question_count < close_count or open_count > close_count + question_count:
        print(":(")
        return

    # Second pass: construct the sequence
    result = []
    open_needed = 0
    close_needed = 0

    for char in s:
        if char == '(':
            result.append('(')
            open_needed += 1
        elif char == ')':
            if open_needed > 0:
                result.append(')')
                open_needed -= 1
            else:
                result.append('(')
                close_needed += 1
        else:
            if open_needed > 0:
                result.append('(')
                open_needed -= 1
            else:
                result.append(')')
                close_needed += 1

    # Adjust the sequence to ensure all strict prefixes are incorrect
    balance = 0
    for i in range(n):
        if result[i] == '(':
            balance += 1
        else:
            balance -= 1

        # If at any point the balance is zero, we need to adjust
        if balance == 0 and i != n - 1:
            result[i] = ')'
            result[i + 1] = '('
            balance = 1

    print(''.join(result))

# Call the function to solve the problem
solve()

