def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    s = data[1]

    stack = []
    result = [''] * n

    for i in range(n):
        if s[i] == '(':
            stack.append(i)
            result[i] = '('
        elif s[i] == ')':
            if stack:
                result[i] = ')'
                stack.pop()
            else:
                # If we encounter a closing parenthesis without a matching opening one,
                # it's impossible to form a valid sequence.
                print(":(")
                return
        else:
            # For '?', we try to balance the parentheses.
            if stack:
                result[i] = ')'
                stack.pop()
            else:
                result[i] = '('
                stack.append(i)

    # If the stack is not empty, it means there are unmatched opening parentheses.
    if stack:
        print(":(")
    else:
        print(''.join(result))

